void kernel_gramschmidt(int ni, int nj, double* A, double* Q, double* R) {
    int nk = ni; // Number of orthonormal basis vectors
    double norm; // Norm of the current vector
    double dotprod; // Dot product of the current vector and the current basis vector
    double* R_copy = new double[nj]; // Copy of R for normalization
    double* Q_copy = new double[ni]; // Copy of Q for normalization
    double* A_copy = new double[nj]; // Copy of A for normalization

    // Parallelization using OpenMP
    #pragma omp parallel for reduction(+:norm, dotprod)
    for (int k = 0; k < nk; k++) {
        norm = 0.0;
        dotprod = 0.0;
        for (int j = 0; j < nj; j++) {
            norm += A[j * ni + k] * A[j * ni + k];
            dotprod += A[j * ni + k] * Q[k];
        }
        norm = sqrt(norm);
        dotprod = sqrt(dotprod);
        R_copy[j] = norm;
        Q_copy[k] = dotprod;
    }

    // Normalization of orthonormal basis vectors
    for (int k = 0; k < ni; k++) {
        Q_copy[k] /= R_copy[k];
    }

    // Deallocation of memory
    delete[] R_copy;
    delete[] Q_copy;
    delete[] A_copy;

    // Copy the orthonormal basis vectors back to Q
    for (int k = 0; k < ni; k++) {
        Q[k] = Q_copy[k];
    }

    // Deallocation of memory
    delete[] Q;
    delete[] R;
}

